const input = require("fs").readFileSync(0, "utf8");

function powerMod(a, b, m) {
  let result = 1n % m;
  let base = a % m;
  while (b > 0n) {
    if ((b & 1n) === 1n) {
      result = (result * base) % m;
    }
    base = (base * base) % m;
    b >>= 1n;
  }
  return result;
}

const [a, b, m] = input.trim().split(/\s+/).map(BigInt);
console.log(powerMod(a, b, m).toString());

