long long powerMod(long long a, long long b, long long m) {
    long long result = 1 % m;
    long long base = a % m;
    while (b > 0) {
        if (b & 1) {
            result = result * base % m;
        }
        base = base * base % m;
        b >>= 1;
    }
    return result;
}

int main() {
    long long a, b, m;
    std::cin >> a >> b >> m;
    std::cout << powerMod(a, b, m) << "\n";
    return 0;
}

