	result := 1 % m
	base := a % m
	for b > 0 {
		if b&1 == 1 {
			result = result * base % m
		}
		base = base * base % m
		b >>= 1
	}
	return result
}

func main() {
	var a, b, m int64
	fmt.Scan(&a, &b, &m)
	fmt.Println(powerMod(a, b, m))
}

